tool_input.command:
mkdir -p src/app/{core/{api,models,time,notify,http},shared/{empty-state,confirm-dialog,page-header},layout,features/{dashboard,tasks,habits,learning,plans,settings}} && rm -f src/app/app.component.html src/app/app.component.scss src/app/app.component.spec.ts && cat > proxy.conf.json <<'EOF'
{
  "/api": {
    "target": "http://localhost:8080",
    "secure": false,
    "changeOrigin": true
  }
}
EOF
jq '.projects.frontend.architect.serve.options = {"proxyConfig": "proxy.conf.json"}' angular.json > /tmp/a.json && mv /tmp/a.json angular.json && sed -i 's#<title>Frontend</title>#<title>QuickFlow</title>#' src/index.html
